/* Public spaces are a released AccountWorld projection on this exact profile site.
 * The profile never copies their material or exposes unreleased draft records. */
static void ph_worlds_teaser(sqlite3 *db,const PhSite *site){
    if(!db||!site)return;
    sqlite3_stmt *rows=NULL;
    if(aw_public_spaces(db,site->id,&rows)!=1){sqlite3_finalize(rows);return;}
    int shown=0;
    while(shown<6&&sqlite3_step(rows)==SQLITE_ROW){
        const char *id=(const char*)sqlite3_column_text(rows,0);
        const char *title=(const char*)sqlite3_column_text(rows,1);
        const char *medium=(const char*)sqlite3_column_text(rows,2);
        const char *look=(const char*)sqlite3_column_text(rows,3);
        const char *lede=(const char*)sqlite3_column_text(rows,4);
        if(!id||!*id||!title||!*title)continue;
        if(!shown)fputs("<style>"
            ".ph-worlds{margin:16px 0 30px}.ph-worlds-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:13px}"
            ".ph-worlds-head h2{margin:0}.ph-worlds-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}"
            ".ph-world-card{display:flex;flex-direction:column;justify-content:flex-end;min-height:175px;gap:9px;padding:22px!important;border:1px solid #b4c6b5;border-radius:19px;background:#e3e8db;color:#1f3a2d!important;overflow:hidden;text-decoration:none}"
            ".ph-world-card strong{display:block;font:400 25px/1.15 Georgia,serif;overflow-wrap:anywhere}.ph-world-card small{font:600 11px/1.35 system-ui;letter-spacing:.08em;text-transform:uppercase;opacity:.78}"
            ".ph-world-card p{margin:0;font-size:13px;line-height:1.5;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}"
            ".ph-world-card[data-look=ticker]{background:#173c33;color:#f1f8e4!important}.ph-world-card[data-look=almanac]{background:#e7d9b9;color:#3c321b!important}"
            ".ph-world-card[data-look=zine]{background:#353047;color:#f4eeeb!important}.ph-world-card[data-look=journal]{background:#f0e6d8;color:#382e27!important}"
            ".ph-world-card:hover,.ph-world-card:focus-visible{border-color:#397853;box-shadow:0 6px 24px #244f3322}"
            ".ph-worlds-all{font:600 13px system-ui}.ph-world-mark svg{width:24px;height:24px}"
            "@media(max-width:650px){.ph-worlds-grid{grid-template-columns:1fr}.ph-world-card{min-height:145px}}"
            "</style><section class=\"ph-worlds\" data-profile-worlds><header class=\"ph-worlds-head\"><h2>Published spaces</h2><span class=\"ph-world-mark\" aria-hidden=\"true\">" BF_ICON_WORLD "</span></header><div class=\"ph-worlds-grid\">",stdout);
        fputs("<a class=\"ph-world-card\" data-look=\"",stdout);html(look?look:"");
        fputs("\" href=\"https://",stdout);html(site->host);fputs("/worlds/",stdout);html(id);
        fputs("\"><small>",stdout);html(medium?medium:"Space");fputs("</small><strong>",stdout);html(title);fputs("</strong>",stdout);
        if(lede&&*lede){fputs("<p>",stdout);html(lede);fputs("</p>",stdout);}
        fputs("</a>",stdout);shown++;
    }
    sqlite3_finalize(rows);
    if(shown){fputs("</div><a class=\"ph-worlds-all\" href=\"https://",stdout);html(site->host);fputs("/worlds\">Browse all spaces</a></section>",stdout);}
}
